handler.function:
console.log('[discovery] Fetching agent cards from A2A servers...');
const servers = { task_agent: 'http://localhost:3001', research_agent: 'http://localhost:3002', quality_agent: 'http://localhost:3003' };

const results = await Promise.allSettled(
  Object.entries(servers).map(async ([key, baseUrl]) => {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 3000);
    try {
      const res = await fetch(`${baseUrl}/.well-known/agent.json`, { signal: controller.signal });
      clearTimeout(timer);
      if (!res.ok) return null;
      const card = await res.json();
      return {
        name: card.name || key,
        url: baseUrl,
        skills: card.skills || [],
        description: card.description || ''
      };
    } catch {
      clearTimeout(timer);
      return null;
    }
  })
);

const availableAgents = results
  .filter(r => r.status === 'fulfilled' && r.value !== null)
  .map(r => r.value);

const agentRegistry = availableAgents.reduce((acc, a) => {
  acc[a.name] = a.url;
  return acc;
}, {});

console.log(`[discovery] Found ${availableAgents.length} agents: ${availableAgents.map(a => a.name).join(', ')}`);
return { availableAgents, agentRegistry };

try {
  console.log('🎯 [orchestrator] Phase:', state.currentPhase, 'UserDecision:', state.userDecision);

  const currentPhase = state.currentPhase || 'task_creation';

  // Agent Card 発見情報からエージェントリストを構築
  const agentsInfo = (state.availableAgents || []).length > 0
    ? state.availableAgents.map(a =>
        `- ${a.name} (${a.url})\n  description: ${a.description}\n  skills: ${JSON.stringify(a.skills)}`
      ).join('\n')
    : '(no agents discovered - will use fallback routing)';

  console.log('[orchestrator] Available agents:\n', agentsInfo);

  // Try to retrieve user message
  let userMessage = null;
  const userMsg1 = state.messages.find(msg => msg.role === 'user');
  if (userMsg1) {
    userMessage = userMsg1.content || userMsg1.text || null;
  }
  if (!userMessage && state.messages.length > 0) {
    const firstMsg = state.messages[0];
    userMessage = firstMsg.content || firstMsg.text || null;
  }

  if (!userMessage) {
    console.error('❌ [orchestrator] Could not find user message');
    throw new Error('User message not found. Please check state.messages.');
  }

  // Skill matching: find best agent for the task
  function findBestAgent(task, phase) {
    const agents = state.availableAgents || [];
    if (agents.length === 0) return null;

    // Score each agent by skill match with task and phase
    const scored = agents.map(agent => {
      let score = 0;
      const taskLower = task.toLowerCase();
      const phaseLower = phase.toLowerCase();

      // Check if agent skills match the task keywords
      for (const skill of (agent.skills || [])) {
        const skillStr = typeof skill === 'string' ? skill : JSON.stringify(skill).toLowerCase();
        if (skillStr.includes(phaseLower) || skillStr.includes(taskLower)) {
          score += 2;
        }
        // Check for keyword overlap
        const words = taskLower.split(/\s+/);
        for (const word of words) {
          if (word.length > 3 && skillStr.includes(word)) {
            score += 1;
          }
        }
      }

      // Bonus for description match
      const descLower = (agent.description || '').toLowerCase();
      for (const word of taskLower.split(/\s+/)) {
        if (word.length > 3 && descLower.includes(word)) {
          score += 1;
        }
      }

      return { agent, score };
    });

    scored.sort((a, b) => b.score - a.score);
    return scored[0].score > 0 ? scored[0].agent : agents[0];
  }

  if (currentPhase === 'task_creation') {
    console.log('📋 [orchestrator] Invoking TaskCreationAgent');

    let prompt = userMessage;
    if (state.userFeedback) {
      prompt = `Feedback on previous task list: ${state.userFeedback}\n\nOriginal request: ${userMessage}`;
      console.log('🔄 [orchestrator] Retry with feedback');
    }

    // Skill matching for task creation
    const bestAgent = findBestAgent(prompt, 'task');
    const agentName = bestAgent ? bestAgent.name : 'TaskCreationAgent';
    console.log('[orchestrator] Selected agent for task_creation:', agentName);

    const systemPrompt = bestAgent
      ? `You are communicating with the ${bestAgent.name} agent (${bestAgent.url}).\n${bestAgent.description ? 'Agent description: ' + bestAgent.description : ''}\n${bestAgent.skills && bestAgent.skills.length > 0 ? 'Agent skills: ' + JSON.stringify(bestAgent.skills) : ''}\n\nYou MUST use ONLY the send_message_to_${bestAgent.name.replace(/\s+/g, '_').toLowerCase()}_agent tool. Do not use any other tools.`
      : 'You MUST use ONLY the send_message_to_task_agent tool. Do not use any other tools.';

    const response = await model.invoke([
      { role: 'system', content: systemPrompt },
      { role: 'user', content: prompt }
    ]);
    return { messages: [response], currentPhase: 'task_creation', userFeedback: null };
  }

  if (currentPhase === 'research_execution') {
    console.log('🔍 [orchestrator] Invoking ResearchExecutionAgent');
    const taskListStr = JSON.stringify(state.taskServerResponse, null, 2);

    let prompt = `Please execute research based on the following task list:\n${taskListStr}`;
    if (state.userFeedback) {
      prompt = `Feedback on previous research: ${state.userFeedback}\n\n${prompt}`;
      console.log('🔄 [orchestrator] Retry research with feedback');
    }

    // Skill matching for research
    const bestAgent = findBestAgent(prompt, 'research');
    const agentName = bestAgent ? bestAgent.name : 'ResearchExecutionAgent';
    console.log('[orchestrator] Selected agent for research_execution:', agentName);

    const systemPrompt = bestAgent
      ? `You are communicating with the ${bestAgent.name} agent (${bestAgent.url}).\n${bestAgent.description ? 'Agent description: ' + bestAgent.description : ''}\n${bestAgent.skills && bestAgent.skills.length > 0 ? 'Agent skills: ' + JSON.stringify(bestAgent.skills) : ''}\n\nYou MUST use ONLY the send_message_to_${bestAgent.name.replace(/\s+/g, '_').toLowerCase()}_agent tool. Do not use any other tools.`
      : 'You MUST use ONLY the send_message_to_research_agent tool. Do not use any other tools.';

    const response = await model.invoke([
      { role: 'system', content: systemPrompt },
      { role: 'user', content: prompt }
    ]);
    return { messages: [response], currentPhase: 'research_execution', userFeedback: null };
  }

  if (currentPhase === 'quality_evaluation') {
    console.log('✅ [orchestrator] Invoking QualityEvaluationAgent');

    // Collect and aggregate all research results
    const allResearchResults = state.messages
      .filter(msg => (msg._getType && msg._getType() === 'tool') || msg.role === 'tool')
      .filter(msg => msg.name === 'send_message_to_research_agent')
      .map(msg => {
        try {
          const parsed = typeof msg.content === 'string' ? JSON.parse(msg.content) : msg.content;
          return parsed;
        } catch (e) {
          console.error('❌ [orchestrator] Failed to parse research result:', e);
          return null;
        }
      })
      .filter(Boolean);

    console.log(`📊 [orchestrator] Collected ${allResearchResults.length} research results`);

    // Get the original user request
    const originalRequest = state.messages.find(msg => msg.role === 'user')?.content || '';

    // Pre-extract research results (resolve nested JSON)
    const extractedResults = [];

    for (const item of allResearchResults) {
      try {
        if (item.response && item.response.content) {
          const contentData = JSON.parse(item.response.content);
          if (contentData.result && contentData.result.messages) {
            const assistantMsg = contentData.result.messages.find(m => m.role === 'assistant');
            if (assistantMsg && assistantMsg.content) {
              const researchData = JSON.parse(assistantMsg.content);
              if (researchData.result && researchData.result.researchResults) {
                extractedResults.push(...researchData.result.researchResults);
              }
            }
          }
        }
      } catch (e) {
        console.error('❌ [orchestrator] Failed to extract research result:', e);
      }
    }

    console.log(`📊 [orchestrator] Extracted ${extractedResults.length} research findings`);

    // Build data for quality evaluation
    const evaluationData = {
      originalRequest,
      researchResults: extractedResults,
      totalResults: extractedResults.length
    };

    const evaluationStr = JSON.stringify(evaluationData, null, 2);

    let prompt = `Please evaluate the quality of the following research results and create an executive summary:\n${evaluationStr}`;
    if (state.userFeedback) {
      prompt = `Feedback on previous evaluation: ${state.userFeedback}\n\n${prompt}`;
      console.log('🔄 [orchestrator] Retry evaluation with feedback');
    }

    // Skill matching for quality evaluation
    const bestAgent = findBestAgent(prompt, 'quality');
    const agentName = bestAgent ? bestAgent.name : 'QualityEvaluationAgent';
    console.log('[orchestrator] Selected agent for quality_evaluation:', agentName);

    const systemPrompt = bestAgent
      ? `You are communicating with the ${bestAgent.name} agent (${bestAgent.url}).\n${bestAgent.description ? 'Agent description: ' + bestAgent.description : ''}\n${bestAgent.skills && bestAgent.skills.length > 0 ? 'Agent skills: ' + JSON.stringify(bestAgent.skills) : ''}\n\nYou MUST use ONLY the send_message_to_${bestAgent.name.replace(/\s+/g, '_').toLowerCase()}_agent tool. Do not use any other tools.`
      : 'You MUST use ONLY the send_message_to_quality_agent tool. Do not use any other tools.';

    const response = await model.invoke([
      { role: 'system', content: systemPrompt },
      { role: 'user', content: prompt }
    ]);
    return { messages: [response], currentPhase: 'quality_evaluation', userFeedback: null };
  }

  console.log('🎯 [orchestrator] No action needed, phase:', currentPhase);
  return { messages: [], currentPhase };
}
catch (error) {
  console.error('❌ [orchestrator] Error:', error);
  return { 
    messages: [{ role: 'assistant', content: `Error: ${error.message}` }],
    currentPhase: 'error'
  };
}

console.log('🚪 [approval_gate_task] Processing task approval');

const lastToolResult = state.messages
  .filter(msg => (msg._getType && msg._getType() === 'tool') || msg.role === 'tool')
  .filter(msg => msg.name === 'send_message_to_task_agent')
  .pop();

if (!lastToolResult) {
  console.log('⚠️  [approval_gate_task] No task agent response found');
  return { messages: [], userDecision: null, currentPhase: state.currentPhase };
}

console.log('📋 [approval_gate_task] Task agent response received');

let parsedContent;
try {
  parsedContent = typeof lastToolResult.content === 'string' 
    ? JSON.parse(lastToolResult.content) 
    : lastToolResult.content;
} catch (e) {
  console.error('❌ [approval_gate_task] Parse error:', e);
  return { messages: [], userDecision: null, currentPhase: state.currentPhase };
}

let taskList = [];

// Structure A: direct content with taskList (A2A tool result)
if (parsedContent.taskList && Array.isArray(parsedContent.taskList)) {
  taskList = parsedContent.taskList;
  console.log('[approval_gate_task] Direct taskList found: ' + taskList.length + ' tasks');
}
// Structure B: nested response.content (legacy)
else if (parsedContent.response && parsedContent.response.content) {
  try {
    const responseContent = typeof parsedContent.response.content === 'string'
      ? JSON.parse(parsedContent.response.content)
      : parsedContent.response.content;

    if (responseContent.result && responseContent.result.messages) {
      const assistantMsg = responseContent.result.messages.find(m => m.role === 'assistant');
      if (assistantMsg && assistantMsg.content) {
        const innerContent = typeof assistantMsg.content === 'string'
          ? JSON.parse(assistantMsg.content)
          : assistantMsg.content;
        taskList = innerContent.result?.taskList || innerContent.taskList || [];
      }
    }
  } catch (e) {
    console.error('❌ [approval_gate_task] Could not parse content:', e);
  }
}
// Structure C: messages array with assistant content containing taskList
else if (parsedContent.messages && Array.isArray(parsedContent.messages)) {
  const assistantMsg = parsedContent.messages.find(m => m.role === 'assistant');
  if (assistantMsg && assistantMsg.content) {
    try {
      const innerContent = typeof assistantMsg.content === 'string'
        ? JSON.parse(assistantMsg.content)
        : assistantMsg.content;
      taskList = innerContent.result?.taskList || innerContent.taskList || [];
    } catch (e) {
      console.error('❌ [approval_gate_task] Could not parse assistant content:', e);
    }
  }
}

if (taskList.length === 0) {
  console.log('⚠️  [approval_gate_task] Empty task list');
  return { messages: [], userDecision: null, currentPhase: state.currentPhase };
}

const taskSummary = taskList.map((t, i) => 
  `${i + 1}. ${t.objective} (${t.estimated_effort || 'N/A'})`
).join('\n');

const totalHours = taskList.reduce((sum, t) => {
  const hours = parseInt(t.estimated_effort) || 0;
  return sum + hours;
}, 0);

const message = `📋 Task List Creation Complete\n\n` +
                `Total Tasks: ${taskList.length}\n` +
                `Estimated Time: ${totalHours} hours\n\n` +
                `Tasks:\n${taskSummary}\n\n` +
                `Proceed with this task list for research?\n` +
                `- Enter "approve" to start research\n` +
                `- Any other input will regenerate the task list`;

console.log('⏸️  [approval_gate_task] Requesting approval');
const userResponse = interrupt(message);
console.log('✅ [approval_gate_task] User response:', userResponse);

if (!userResponse) {
  return {
    messages: [],
    userDecision: 'pending',
    currentPhase: state.currentPhase,
    taskServerResponse: parsedContent
  };
}

const response = String(userResponse).toLowerCase().trim();
if (response === 'approve') {
  console.log('✅ [approval_gate_task] Approved - moving to research');
  return {
    messages: [],
    userDecision: 'approve',
    currentPhase: 'research_execution',
    taskServerResponse: parsedContent,
    userFeedback: null
  };
} else {
  console.log('❌ [approval_gate_task] Rejected - retrying task creation');
  return {
    messages: [],
    userDecision: 'reject',
    currentPhase: 'task_creation',
    taskServerResponse: parsedContent,
    userFeedback: userResponse
  };
}

console.log('🚪 [approval_gate_research] Processing research approval');

const lastToolResult = state.messages
  .filter(msg => (msg._getType && msg._getType() === 'tool') || msg.role === 'tool')
  .filter(msg => msg.name === 'send_message_to_research_agent')
  .pop();

if (!lastToolResult) {
  console.log('⚠️  [approval_gate_research] No research agent response found');
  return { messages: [], userDecision: null, currentPhase: state.currentPhase };
}

console.log('🔍 [approval_gate_research] Research agent response received');

let parsedContent;
try {
  parsedContent = typeof lastToolResult.content === 'string'
    ? JSON.parse(lastToolResult.content)
    : lastToolResult.content;
} catch (e) {
  console.error('❌ [approval_gate_research] Parse error:', e);
  return { messages: [], userDecision: null, currentPhase: state.currentPhase };
}

let researchResults = [];
let summary = '';

// Structure A: direct content with researchResults (A2A tool result)
if (parsedContent.researchResults && Array.isArray(parsedContent.researchResults)) {
  researchResults = parsedContent.researchResults;
  console.log('[approval_gate_research] Direct researchResults found: ' + researchResults.length + ' results');
}
// Structure B: nested response.content (legacy)
else if (parsedContent.response && parsedContent.response.content) {
  try {
    const responseContent = typeof parsedContent.response.content === 'string'
      ? JSON.parse(parsedContent.response.content)
      : parsedContent.response.content;

    if (responseContent.result && responseContent.result.messages) {
      const assistantMsg = responseContent.result.messages.find(m => m.role === 'assistant');
      if (assistantMsg && assistantMsg.content) {
        const innerContent = typeof assistantMsg.content === 'string'
          ? JSON.parse(assistantMsg.content)
          : assistantMsg.content;
        researchResults = innerContent.result?.researchResults || innerContent.researchResults || [];
        summary = innerContent.result?.summary || innerContent.summary || '';
      }
    }
  } catch (e) {
    console.error('❌ [approval_gate_research] Could not parse content:', e);
  }
}
// Structure C: messages array with assistant content containing researchResults
else if (parsedContent.messages && Array.isArray(parsedContent.messages)) {
  const assistantMsg = parsedContent.messages.find(m => m.role === 'assistant');
  if (assistantMsg && assistantMsg.content) {
    try {
      const innerContent = typeof assistantMsg.content === 'string'
        ? JSON.parse(assistantMsg.content)
        : assistantMsg.content;
      researchResults = innerContent.result?.researchResults || innerContent.researchResults || [];
      summary = innerContent.result?.summary || innerContent.summary || '';
    } catch (e) {
      console.error('❌ [approval_gate_research] Could not parse assistant content:', e);
    }
  }
}

if (researchResults.length === 0) {
  console.log('⚠️  [approval_gate_research] Empty research results');
  return { messages: [], userDecision: null, currentPhase: state.currentPhase };
}

const resultSummary = researchResults.map((r, i) =>
  `${i + 1}. ${r.objective}\n   ${r.findings.substring(0, 100)}...`
).join('\n\n');

const message = `🔍 Research Execution Complete\n\n` +
                `Completed Tasks: ${researchResults.length}\n\n` +
                `Research Results:\n${resultSummary}\n\n` +
                `Summary: ${summary}\n\n` +
                `Proceed with quality evaluation for these research results?\n` +
                `- Enter "approve" to start quality evaluation\n` +
                `- Any other input will re-execute the research`;

console.log('⏸️  [approval_gate_research] Requesting approval');
const userResponse = interrupt(message);
console.log('✅ [approval_gate_research] User response:', userResponse);

if (!userResponse) {
  return {
    messages: [],
    userDecision: 'pending',
    currentPhase: state.currentPhase,
    researchServerResponse: parsedContent
  };
}

const response = String(userResponse).toLowerCase().trim();
if (response === 'approve') {
  console.log('✅ [approval_gate_research] Approved - moving to evaluation');
  return {
    messages: [],
    userDecision: 'approve',
    currentPhase: 'quality_evaluation',
    researchServerResponse: parsedContent,
    userFeedback: null
  };
} else {
  console.log('❌ [approval_gate_research] Rejected - retrying research');
  return {
    messages: [],
    userDecision: 'reject',
    currentPhase: 'research_execution',
    researchServerResponse: parsedContent,
    userFeedback: userResponse
  };
}

console.log('📊 [report_generator] Report generation started');

// Collect all research results
const allResearchResults = state.messages
  .filter(msg => (msg._getType && msg._getType() === 'tool') || msg.role === 'tool')
  .filter(msg => msg.name === 'send_message_to_research_agent')
  .map(msg => {
    try {
      const parsed = typeof msg.content === 'string' ? JSON.parse(msg.content) : msg.content;
      return parsed;
    } catch (e) {
      console.error('❌ [report_generator] Failed to parse research result:', e);
      return null;
    }
  })
  .filter(Boolean);

console.log(`📊 [report_generator] Collected ${allResearchResults.length} research results`);

// Get the original user request
const originalRequest = state.messages.find(msg => msg.role === 'user')?.content || '';

// Extract research results (resolve nested JSON)
const extractedResults = [];

for (const item of allResearchResults) {
  try {
    if (item.response && item.response.content) {
      const contentData = JSON.parse(item.response.content);
      if (contentData.result && contentData.result.messages) {
        const assistantMsg = contentData.result.messages.find(m => m.role === 'assistant');
        if (assistantMsg && assistantMsg.content) {
          const researchData = JSON.parse(assistantMsg.content);
          if (researchData.result && researchData.result.researchResults) {
            extractedResults.push(...researchData.result.researchResults);
          }
        }
      }
    }
  } catch (e) {
    console.error('❌ [report_generator] Failed to extract research result:', e);
  }
}

console.log(`📊 [report_generator] Extracted ${extractedResults.length} research findings`);

// Calculate statistics
const totalResults = extractedResults.length;
const totalCharacters = extractedResults.reduce((sum, r) => sum + (r.findings?.length || 0), 0);

// Generate integrated report
let reportText = '# Research Report\n\n';
reportText += '## Overview\n\n';
reportText += `**Original User Request**: ${originalRequest}\n\n`;
reportText += `**Completed Tasks**: ${totalResults}\n`;
reportText += `**Total Characters**: ${totalCharacters.toLocaleString()}characters\n\n`;

reportText += '## Research Results Summary\n\n';
extractedResults.forEach((r, i) => {
  reportText += `${i + 1}. **${r.objective}**\n`;
  const summary = r.findings.substring(0, 150);
  reportText += `   ${summary}${r.findings.length > 150 ? '...' : ''}\n\n`;
});

reportText += '## Detailed Research Results\n\n';
extractedResults.forEach((r, i) => {
  reportText += `### Task${i + 1}: ${r.objective}\n\n`;
  reportText += `${r.findings}\n\n`;
  if (r.sources && r.sources.length > 0) {
    reportText += `**Sources**:\n`;
    r.sources.forEach(src => {
      reportText += `- ${src}\n`;
    });
    reportText += '\n';
  }
});

// Create flattened data structure
const reportData = {
  originalRequest,
  researchResults: extractedResults,
  totalResults,
  totalCharacters
};

console.log('✅ [report_generator] Report generation complete');
console.log(`  - Tasks: ${totalResults}`);
console.log(`  - Total characters: ${totalCharacters}`);
console.log(`  - Report Length: ${reportText.length} chars`);

return {
  messages: [],
  reportData,
  reportText,
  currentPhase: state.currentPhase
};

console.log('🚪 [approval_gate_report] Processing report approval');

if (!state.reportText) {
  console.log('⚠️  [approval_gate_report] No report text found');
  return { messages: [], userDecision: null, currentPhase: state.currentPhase };
}

console.log('📊 [approval_gate_report] Report generated');

const message = `📊 Research Report Generation Complete\n\n` +
                `Completed Tasks: ${state.reportData?.totalResults || 0}\n` +
                `Total characters: ${(state.reportData?.totalCharacters || 0).toLocaleString()}\n\n` +
                `${state.reportText}\n\n` +
                `Proceed with quality evaluation for this report?\n` +
                `- Enter "approve" to start quality evaluation\n` +
                `- Any other input will re-execute the research`;

console.log('⏸️  [approval_gate_report] Requesting approval');
const userResponse = interrupt(message);
console.log('✅ [approval_gate_report] User response:', userResponse);

if (!userResponse) {
  return {
    messages: [],
    userDecision: 'pending',
    currentPhase: state.currentPhase
  };
}

const response = String(userResponse).toLowerCase().trim();
if (response === 'approve') {
  console.log('✅ [approval_gate_report] Approved - moving to quality evaluation');
  return {
    messages: [],
    userDecision: 'approve',
    currentPhase: 'quality_evaluation',
    userFeedback: null
  };
} else {
  console.log('❌ [approval_gate_report] Rejected - retrying research');
  return {
    messages: [],
    userDecision: 'reject',
    currentPhase: 'research_execution',
    userFeedback: userResponse
  };
}

console.log('🚪 [approval_gate_evaluation] Processing evaluation approval');

const lastToolResult = state.messages
  .filter(msg => (msg._getType && msg._getType() === 'tool') || msg.role === 'tool')
  .filter(msg => msg.name === 'send_message_to_quality_agent')
  .pop();

if (!lastToolResult) {
  console.log('⚠️  [approval_gate_evaluation] No quality agent response found');
  return { messages: [], userDecision: null, currentPhase: state.currentPhase };
}

console.log('✅ [approval_gate_evaluation] Quality agent response received');

let parsedContent;
try {
  parsedContent = typeof lastToolResult.content === 'string'
    ? JSON.parse(lastToolResult.content)
    : lastToolResult.content;
} catch (e) {
  console.error('❌ [approval_gate_evaluation] Parse error:', e);
  return { messages: [], userDecision: null, currentPhase: state.currentPhase };
}

let qualityScore = 0;
let executiveSummary = '';
let recommendations = [];
let missingTopics = [];

// Structure A: direct content with evaluation fields (A2A tool result)
if (parsedContent.qualityScore !== undefined) {
  qualityScore = parsedContent.qualityScore;
  executiveSummary = parsedContent.executiveSummary || '';
  recommendations = parsedContent.recommendations || [];
  missingTopics = parsedContent.missingTopics || [];
  console.log('[approval_gate_evaluation] Direct evaluation fields found');
}
// Structure B: nested response.content (legacy)
else if (parsedContent.response && parsedContent.response.content) {
  try {
    const responseContent = typeof parsedContent.response.content === 'string'
      ? JSON.parse(parsedContent.response.content)
      : parsedContent.response.content;

    if (responseContent.result && responseContent.result.messages) {
      const assistantMsg = responseContent.result.messages.find(m => m.role === 'assistant');
      if (assistantMsg && assistantMsg.content) {
        const innerContent = typeof assistantMsg.content === 'string'
          ? JSON.parse(assistantMsg.content)
          : assistantMsg.content;
        const result = innerContent.result || innerContent;
        qualityScore = result.qualityScore || 0;
        executiveSummary = result.executiveSummary || '';
        recommendations = result.recommendations || [];
        missingTopics = result.missingTopics || [];
      }
    }
  } catch (e) {
    console.error('❌ [approval_gate_evaluation] Could not parse content:', e);
  }
}
// Structure C: messages array with assistant content containing evaluation
else if (parsedContent.messages && Array.isArray(parsedContent.messages)) {
  const assistantMsg = parsedContent.messages.find(m => m.role === 'assistant');
  if (assistantMsg && assistantMsg.content) {
    try {
      const innerContent = typeof assistantMsg.content === 'string'
        ? JSON.parse(assistantMsg.content)
        : assistantMsg.content;
      const result = innerContent.result || innerContent;
      qualityScore = result.qualityScore || 0;
      executiveSummary = result.executiveSummary || '';
      recommendations = result.recommendations || [];
      missingTopics = result.missingTopics || [];
    } catch (e) {
      console.error('❌ [approval_gate_evaluation] Could not parse assistant content:', e);
    }
  }
}

const recList = recommendations.length > 0
  ? recommendations.map((r, i) => `  ${i + 1}. ${r}`).join('\n')
  : '  None';

const missingList = missingTopics.length > 0
  ? missingTopics.join(', ')
  : 'None';

const message = `✅ Quality Evaluation Complete\n\n` +
                `Quality Score: ${qualityScore}/100\n\n` +
                `Executive Summary:\n${executiveSummary}\n\n` +
                `Recommendations:\n${recList}\n\n` +
                `Missing Topics: ${missingList}\n\n` +
                `Complete with these evaluation results?\n` +
                `- Enter "approve" to complete the workflow\n` +
                `- Any other input will re-execute the evaluation`;

console.log('⏸️  [approval_gate_evaluation] Requesting approval');
const userResponse = interrupt(message);
console.log('✅ [approval_gate_evaluation] User response:', userResponse);

if (!userResponse) {
  return {
    messages: [],
    userDecision: 'pending',
    currentPhase: state.currentPhase,
    evaluationServerResponse: parsedContent
  };
}

const response = String(userResponse).toLowerCase().trim();
if (response === 'approve') {
  console.log('✅ [approval_gate_evaluation] Approved - workflow completed');
  return {
    messages: [{ role: 'assistant', content: '✅ Workflow completed successfully.' }],
    userDecision: 'approve',
    currentPhase: 'completed',
    evaluationServerResponse: parsedContent,
    userFeedback: null
  };
} else {
  console.log('❌ [approval_gate_evaluation] Rejected - retrying evaluation');
  return {
    messages: [],
    userDecision: 'reject',
    currentPhase: 'quality_evaluation',
    evaluationServerResponse: parsedContent,
    userFeedback: userResponse
  };
}

const lastMessage = state.messages[state.messages.length - 1];
if (lastMessage && lastMessage.tool_calls && lastMessage.tool_calls.length > 0) {
  return 'tools';
}
if (state.currentPhase === 'error' || state.currentPhase === 'completed') {
  return '__end__';
}
return '__end__';

const lastToolResult = state.messages
  .filter(msg => (msg._getType && msg._getType() === 'tool') || msg.role === 'tool')
  .pop();

if (!lastToolResult) {
  return '__end__';
}

if (lastToolResult.name === 'send_message_to_task_agent') {
  return 'approval_gate_task';
}
if (lastToolResult.name === 'send_message_to_research_agent') {
  return 'approval_gate_research';
}
if (lastToolResult.name === 'send_message_to_quality_agent') {
  return 'approval_gate_evaluation';
}

return '__end__';
